function decodificar(b64) {
  // Los binarios viajan en base64 dentro del item mientras el modo de binarios
  // sea el de memoria, que es el de serie. Buffer existe en el nodo Code, pero
  // el runner podria no exponerlo: de ahi el plan B.
  if (typeof Buffer !== 'undefined') return Buffer.from(b64, 'base64').toString('utf8');
  const bin = atob(b64);
  return new TextDecoder('utf-8').decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)));
}

function leerVault() {
  // Segun la version de n8n, el nodo de lectura saca un item por fichero o un
  // solo item con data0, data1... Recorremos items y propiedades a la vez, que
  // cubre las dos formas sin preguntar.
  const ficheros = [];
  for (const item of $input.all()) {
    for (const clave of Object.keys(item.binary ?? {})) {
      const b = item.binary[clave];
      if (!b || typeof b.data !== 'string') continue;
      ficheros.push({
        nombre: b.fileName ?? clave,
        texto: decodificar(b.data),
      });
    }
  }
  return ficheros;
}

function frontmatter(texto) {
  // Un parser de YAML de tres lineas. Solo hay que leer lo que escribe
  // "Componer nota", que son pares clave: valor planos.
  const m = texto.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return {};
  const campos = {};
  for (const linea of m[1].split(/\r?\n/)) {
    const i = linea.indexOf(':');
    if (i === -1) continue;
    const clave = linea.slice(0, i).trim();
    let valor = linea.slice(i + 1).trim();
    if (valor.startsWith('"') && valor.endsWith('"')) {
      valor = valor.slice(1, -1).replace(/\\"/g, '"');
    }
    campos[clave] = valor;
  }
  return campos;
}

// Modo: Run Once for All Items.
// Saca un item por nota del vault, con la misma forma que "Indexar la nota" de
// 02b. El cuerpo se corta antes de la transcripcion cruda: lo que se indexa es
// la version limpia, igual que cuando la nota entro por primera vez.

function cuerpo(texto) {
  const sinFrontmatter = texto.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, '');
  const corte = sinFrontmatter.search(/<!--\s*transcripci/i);
  const util = corte === -1 ? sinFrontmatter : sinFrontmatter.slice(0, corte);
  // El titulo ya va aparte en el texto indexable, asi que se quita el "# ".
  return util.replace(/^#\s+.*\r?\n?/, '').trim();
}

const salida = [];

for (const f of leerVault()) {
  const fm = frontmatter(f.texto);
  const titulo = fm.titulo || f.nombre.replace(/\.md$/, '');
  const limpio = cuerpo(f.texto);
  if (!limpio) continue;                     // nota vacia, nada que indexar

  salida.push({
    json: {
      fichero: f.nombre,
      titulo,
      tipo: fm.tipo || 'nota',
      cuando: fm.cuando || '',
      tags: (fm.tags || '').replace(/^\[|\]$/g, '').trim(),
      creado: fm.creado || '',
      texto: titulo + '\n\n' + limpio,
    },
  });
}

return salida;
